static mb_ipc_route_t * ipc_router_search_route(u8 dst_cpu, u32 * route_id)
{
	mb_ipc_route_t  * ipc_route = NULL;
	for(int i = 0; i < ARRAY_SIZE(ipc_route_tbl); i++)
